SELECT * FROM ( SELECT HANDLE_STATION_CODE, HANDLE_DATE_TIME, LAST_HANDLE_STATION_CODE, LAST_HANDLE_DATE_TIME, TRX_AMOUNT, OVERTIME_AMOUNT, HANDLE_RESULT_CODE, TICKET_TRANS_SEQ, RESERVE1, TO_CHAR(CREATE_TIME, 'YYYYMMDDHH24MISS') AS PAY_ORDER_NO_DATE, SIGN_CHANNEL_CODE, LAST_TICKET_STATUS, RESERVE2, TRX_TYPE, CARD_ID, CARD_TYPE, DEVICE_ID, ROW_NUMBER() OVER (ORDER BY HANDLE_DATE_TIME DESC, ID DESC) AS rn FROM QRCODE_TXN_DETAIL WHERE 1=1
AND ITP_USER_ID = #{thirdUserId,jdbcType=VARCHAR}
AND CARD_ID IN
#{item,jdbcType=VARCHAR}
AND CARD_TYPE = #{cardType}
AND TXN_DATE >= #{startDate}
AND TXN_DATE <= #{endDate}
) WHERE rn > #{offset} AND rn <= #{offsetEnd}

