SELECT page.*, currentStation.STATION_NAME AS handleStationName, lastStation.STATION_NAME AS lastHandleStationName FROM ( SELECT ID AS id, DEVICE_ID AS deviceId, ITP_USER_ID AS itpUserId, TRX_TYPE AS trxType, ISSUE_CHANNEL_CODE AS issueChannelCode, SIGN_CHANNEL_CODE AS signChannelCode, CARD_ID AS cardId, CARD_TYPE AS cardType, HANDLE_DATE_TIME AS handleDateTime, TXN_DATE AS txnDate, HANDLE_STATION_CODE AS handleStationCode, TRX_AMOUNT AS trxAmount, OVERTIME_AMOUNT AS overtimeAmount, LAST_TICKET_STATUS AS lastTicketStatus, HANDLE_RESULT_CODE AS handleResultCode, LAST_HANDLE_STATION_CODE AS lastHandleStationCode, LAST_HANDLE_DATE_TIME AS lastHandleDateTime, TICKET_TRANS_SEQ AS ticketTransSeq, CREATE_TIME AS createTime, ROW_NUMBER() OVER (ORDER BY HANDLE_DATE_TIME DESC, ID DESC) AS rn FROM QRCODE_TXN_DETAIL WHERE 1 = 1
AND CARD_ID = #{cardId,jdbcType=VARCHAR}
AND ITP_USER_ID = #{thirdUserId,jdbcType=VARCHAR}
AND SIGN_CHANNEL_CODE = #{signChannelCode,jdbcType=VARCHAR}
AND CARD_TYPE = #{cardType,jdbcType=VARCHAR}
AND TXN_DATE >= #{startDate,jdbcType=VARCHAR}
AND TXN_DATE <= #{endDate,jdbcType=VARCHAR}
) page LEFT JOIN STATION_INFO currentStation ON currentStation.STATION_CODE = page.handleStationCode LEFT JOIN STATION_INFO lastStation ON lastStation.STATION_CODE = page.lastHandleStationCode WHERE page.rn > #{offset} AND page.rn <= #{offsetEnd}

