SELECT * FROM ( SELECT HANDLE_STATION_CODE, HANDLE_DATE_TIME, LAST_HANDLE_STATION_CODE, LAST_HANDLE_DATE_TIME, TRX_AMOUNT, NVL(TRX_AMOUNT, 0) + NVL(OVERTIME_AMOUNT, 0) AS TOTAL_AMOUNT, TICKET_TRANS_SEQ, RESERVE1, TO_CHAR(CREATE_TIME, 'YYYYMMDDHH24MISS') AS PAY_ORDER_NO_DATE, SIGN_CHANNEL_CODE, RESERVE2, TRX_TYPE, CARD_ID, CARD_TYPE, ROW_NUMBER() OVER (ORDER BY HANDLE_DATE_TIME DESC, ID DESC) AS rn FROM QRCODE_TXN_DETAIL WHERE ISSUE_CHANNEL_CODE = '07'
AND ITP_USER_ID = #{thirdUserId}
AND TXN_DATE >= #{startDate}
AND TXN_DATE <= #{endDate}
) WHERE rn > #{offset} AND rn <= #{offsetEnd}

SELECT COUNT(1)
FROM QRCODE_TXN_DETAIL
WHERE ISSUE_CHANNEL_CODE = '07'

      AND ITP_USER_ID = #{thirdUserId}


      AND TXN_DATE >= #{startDate}


