SELECT ID AS id,
       CARD_ID AS cardId,
       TRX_TYPE AS trxType,
       HANDLE_DATE_TIME AS handleDateTime,
       TICKET_TRANS_SEQ AS ticketTransSeq,
       DEVICE_ID AS deviceId
FROM QRCODE_TXN_DETAIL
WHERE CARD_ID = #{cardId,jdbcType=VARCHAR}
  AND TRX_TYPE = #{trxType,jdbcType=VARCHAR}
  AND HANDLE_DATE_TIME = #{handleDateTime,jdbcType=VARCHAR}
  AND TICKET_TRANS_SEQ = #{ticketTransSeq,jdbcType=VARCHAR}

SELECT
    COUNT(1) AS count,
    ROUND(SUM(NVL(TRX_AMOUNT, 0)) / 100, 2) AS totalDebit,
    ROUND(SUM(NVL(TRX_AMOUNT, 0) + NVL(OVERTIME_AMOUNT, 0)) / 100, 2) AS totalPrice,
    ROUND(SUM(NVL(OVERTIME_AMOUNT, 0)) / 100, 2) AS totalDiscount
FROM QRCODE_TXN_DETAIL
WHERE TRX_TYPE IN ('02', '03')

